document.addEventListener('DOMContentLoaded', () => {
    // Intersection Observer for scroll animations
    const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                entry.target.classList.add('visible');
            }
        });
    }, {
        threshold: 0.1
    });

    const elementsToAnimate = document.querySelectorAll('.feature-item, .screenshot-gallery figure, .tech-stack ul');
    elementsToAnimate.forEach(el => {
        observer.observe(el);
    });

    // Sticky Nav active link highlighting
    const navLinks = document.querySelectorAll('.main-nav a');
    const sections = document.querySelectorAll('main section');

    const sectionObserver = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                navLinks.forEach(link => {
                    const href = link.getAttribute('href');
                    if (href.substring(1) === entry.target.id) {
                        link.classList.add('active');
                    } else {
                        link.classList.remove('active');
                    }
                });
            }
        });
    }, { rootMargin: "-50% 0px -50% 0px", threshold: 0 });

    sections.forEach(section => {
        sectionObserver.observe(section);
    });


    // Modal logic
    const modal = document.getElementById("myModal");
    const modalImg = document.getElementById("img01");
    const galleryImages = document.querySelectorAll(".screenshot-gallery img");
    const closeModal = document.querySelector(".close-modal");

    if (modal && modalImg && galleryImages.length > 0 && closeModal) {
        galleryImages.forEach(img => {
            img.onclick = function(){
                modal.style.display = "flex";
                modalImg.src = this.src;
            }
        });

        const close = () => {
            modal.style.display = "none";
        }

        closeModal.onclick = close;

        modal.onclick = function(event) {
            if (event.target === modal) {
                close();
            }
        }
    }

    // --- Guide Simulator Logic ---
    const visualGrid = document.getElementById('visual-grid');
    if (visualGrid) {
        const audioStimulus = document.getElementById('audio-stimulus');
        const audioNBack = document.getElementById('audio-n-back');
        const nextTrialBtn = document.getElementById('next-trial-btn');
        const resetBtn = document.getElementById('reset-btn');
        const nLevelSelector = document.getElementById('n-level-selector');
        const trialCountSpan = document.getElementById('trial-count');
        const explanationDiv = document.getElementById('explanation');
        const guideNavController = document.querySelector('.guide-header');

        let gridCells = [];
        for (let i = 0; i < 9; i++) {
            const cell = document.createElement('div');
            cell.classList.add('grid-cell');
            cell.dataset.index = i;
            visualGrid.appendChild(cell);
            gridCells.push(cell);
        }

        const audioChars = ['C', 'H', 'K', 'L', 'Q', 'R', 'S', 'T'];
        let state = {
            nLevel: 2,
            trialIndex: 0,
            history: [], // { visual: number, audio: string }
            isTutorialMatchScheduled: true,
        };

        function updateNSelectorUI() {
            nLevelSelector.querySelectorAll('button').forEach(btn => {
                btn.classList.toggle('active', parseInt(btn.dataset.n) === state.nLevel);
            });
        }

        function resetSimulation() {
            state.trialIndex = 0;
            state.history = [];
            state.isTutorialMatchScheduled = true;
            trialCountSpan.textContent = 0;
            audioStimulus.textContent = '-';
            audioNBack.textContent = '-';
            gridCells.forEach(cell => cell.className = 'grid-cell');
            const lang = document.documentElement.lang.startsWith('zh') ? 'zh' : 'en';
            explanationDiv.innerHTML = lang === 'zh' 
                ? '已重置。点击“下一步”开始教学演示。'
                : 'Reset. Click "Next Step" to begin the tutorial demonstration.';
            explanationDiv.className = 'explanation-box info';
        }

        function runNextTrial() {
            state.trialIndex++;
            trialCountSpan.textContent = state.trialIndex;

            gridCells.forEach(cell => cell.className = 'grid-cell');

            let visualStimulus, audioStimulusChar;
            let isTutorialMatch = false;

            if (state.isTutorialMatchScheduled && state.trialIndex === state.nLevel + 1) {
                const targetStimulus = state.history[0];
                visualStimulus = targetStimulus.visual;
                audioStimulusChar = targetStimulus.audio;
                isTutorialMatch = true;
                state.isTutorialMatchScheduled = false;
            } else {
                visualStimulus = Math.floor(Math.random() * 9);
                audioStimulusChar = audioChars[Math.floor(Math.random() * audioChars.length)];
            }

            state.history.push({ visual: visualStimulus, audio: audioStimulusChar });

            gridCells[visualStimulus].classList.add('current-stimulus');
            audioStimulus.textContent = audioStimulusChar;

            const lang = document.documentElement.lang.startsWith('zh') ? 'zh' : 'en';
            let explanationText, matchText;

            if (lang === 'zh') {
                explanationText = `第 ${state.trialIndex} 轮：<br>当前位置: ${visualStimulus + 1}号格, 当前字母: '${audioStimulusChar}'`;
            } else {
                explanationText = `Trial ${state.trialIndex}:<br>Current Position: Grid ${visualStimulus + 1}, Current Letter: '${audioStimulusChar}'`;
            }

            let visualMatch = false;
            let audioMatch = false;

            if (state.trialIndex > state.nLevel) {
                const nBackIndex = state.trialIndex - 1 - state.nLevel;
                const nBackStimulus = state.history[nBackIndex];

                audioNBack.textContent = nBackStimulus.audio;
                gridCells[nBackStimulus.visual].classList.add('n-back-match');

                if (nBackStimulus.visual === visualStimulus) visualMatch = true;
                if (nBackStimulus.audio === audioStimulusChar) audioMatch = true;

                if (lang === 'zh') {
                    explanationText += `<br>N=${state.nLevel}步前位置: ${nBackStimulus.visual + 1}号格, 字母: '${nBackStimulus.audio}'`;
                } else {
                    explanationText += `<br>N=${state.nLevel} steps back: Position ${nBackStimulus.visual + 1}, Letter: '${nBackStimulus.audio}'`;
                }
            } else {
                audioNBack.textContent = '-';
                if (lang === 'zh') {
                    explanationText += `<br>正在记录历史...还需要 ${state.nLevel - state.trialIndex + 1} 轮才能开始判断。`;
                } else {
                    explanationText += `<br>Recording history... ${state.nLevel - state.trialIndex + 1} more trials until matching begins.`;
                }
            }

            if (isTutorialMatch) {
                explanationDiv.className = 'explanation-box success';
                if (lang === 'zh') {
                    explanationText += `<br><strong class="font-bold">教学时刻：这是一个双重匹配！</strong><br>请注意，当前刺激（位置和字母）与${state.nLevel}步前的完全相同。在真实游戏中，您需要同时按下视觉和听觉的匹配按钮。`;
                } else {
                    explanationText += `<br><strong class="font-bold">Teaching Moment: This is a dual match!</strong><br>Notice the current stimulus (position and letter) is identical to the one from ${state.nLevel} steps ago. In a real game, you would press both the visual and audio match keys.`;
                }
            } else if (visualMatch || audioMatch) {
                explanationDiv.className = 'explanation-box success';
                if (lang === 'zh') {
                    matchText = [];
                    if (visualMatch) matchText.push("视觉匹配");
                    if (audioMatch) matchText.push("听觉匹配");
                    explanationText += `<br><strong class="font-bold">出现${matchText.join('和')}！</strong>`;
                } else {
                    matchText = [];
                    if (visualMatch) matchText.push("Visual Match");
                    if (audioMatch) matchText.push("Audio Match");
                    explanationText += `<br><strong class="font-bold">${matchText.join(' and ')}!</strong>`;
                }
            } else {
                explanationDiv.className = 'explanation-box info';
                if (state.trialIndex > state.nLevel) {
                    if (lang === 'zh') {
                        explanationText += "<br>均不匹配。";
                    } else {
                        explanationText += "<br>No match.";
                    }
                }
            }

            explanationDiv.innerHTML = explanationText;
        }

        nLevelSelector.addEventListener('click', (e) => {
            if (e.target.tagName === 'BUTTON') {
                state.nLevel = parseInt(e.target.dataset.n);
                updateNSelectorUI();
                resetSimulation();
            }
        });

        nextTrialBtn.addEventListener('click', runNextTrial);
        resetBtn.addEventListener('click', resetSimulation);

        const guideSections = document.querySelectorAll('.guide-container section');
        const guideNavLinks = document.querySelectorAll('.guide-header .nav-link');

        const guideObserver = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    guideNavLinks.forEach(link => {
                        const isActive = link.getAttribute('href').substring(1) === entry.target.id;
                        link.classList.toggle('active', isActive);
                    });
                }
            });
        }, { rootMargin: "-40% 0px -60% 0px", threshold: 0 });

        guideSections.forEach(section => guideObserver.observe(section));

        // Sticky guide nav logic
        const guideNavObserver = new IntersectionObserver(
            ([e]) => e.target.classList.toggle('is-pinned', e.intersectionRatio < 1),
            {threshold: [1]}
        );
        if(guideNavController) guideNavObserver.observe(guideNavController);

        updateNSelectorUI();
        resetSimulation();
    }
});

// Add a simple animation style to the head
const style = document.createElement('style');
style.innerHTML = `
    .feature-item, .screenshot-gallery figure, .tech-stack ul {
        opacity: 0;
        transform: translateY(20px);
        transition: opacity 0.6s ease-out, transform 0.6s ease-out;
    }

    .feature-item.visible, .screenshot-gallery figure.visible, .tech-stack ul.visible {
        opacity: 1;
        transform: translateY(0);
    }

    .guide-header {
        transition: top 0.3s;
        top: -100px; /* Start hidden */
    }

    .guide-header.is-pinned {
        top: 0;
    }
`;
document.head.appendChild(style);

import { useState, useEffect } from 'react';

function getStorageValue<T>(key: string, defaultValue: T): T {
  // getting stored value
  if (typeof window !== 'undefined') {
    const saved = window.localStorage.getItem(key);
    if (saved !== null) {
      try {
        return JSON.parse(saved);
      } catch (error) {
        console.error(`Error parsing localStorage key "${key}":`, error);
        return defaultValue;
      }
    }
  }
  return defaultValue;
}

export function useLocalStorage<T>(key: string, defaultValue: T): [T, React.Dispatch<React.SetStateAction<T>>] {
  const [value, setValue] = useState(() => {
    return getStorageValue(key, defaultValue);
  });

  useEffect(() => {
    // storing value
    window.localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);

  return [value, setValue];
}

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;700;800&display=swap');

:root {
    --primary-bg: #fdfdff;
    --secondary-bg: #f4f7fa;
    --card-bg: #ffffff;
    --text-color: #1a202c;
    --light-text-color: #4a5568;
    --accent-color: #4f46e5;
    --accent-gradient: linear-gradient(45deg, #4f46e5, #818cf8);
    --border-color: #e2e8f0;
    --shadow-color: rgba(0, 0, 0, 0.05);
}

body {
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    background-color: var(--primary-bg);
    color: var(--light-text-color);
    margin: 0;
    line-height: 1.7;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
}

.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 2rem;
}

h1, h2, h3 {
    color: var(--text-color);
    font-weight: 800;
}

h2 {
    text-align: center;
    font-size: 2.8rem;
    margin-bottom: 4rem;
    position: relative;
}

h2::after {
    content: '';
    display: block;
    width: 70px;
    height: 5px;
    background: var(--accent-gradient);
    margin: 12px auto 0;
    border-radius: 3px;
}

/* Language Switcher */
.language-switcher {
    position: absolute;
    top: 1.5rem;
    right: 2rem;
    font-size: 1rem;
    background: rgba(31, 41, 55, 0.5);
    padding: 0.5rem 1rem;
    border-radius: 20px;
    backdrop-filter: blur(8px);
    border: 1px solid rgba(255, 255, 255, 0.1);
}

.language-switcher a {
    color: #d1d5db;
    text-decoration: none;
    transition: color 0.3s;
    font-weight: 500;
}

.language-switcher a:hover {
    color: white;
}

.language-switcher span {
    color: white;
    font-weight: 700;
}

/* Hero Section */
.hero {
    position: relative;
    background-color: #111827;
    color: white;
    padding: 8rem 0;
    text-align: center;
    overflow: hidden;
}

.hero::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: 
        radial-gradient(circle at 15% 50%, rgba(124, 58, 237, 0.2), transparent 40%),
        radial-gradient(circle at 85% 30%, rgba(59, 130, 246, 0.15), transparent 40%);
    opacity: 0.5;
}

.hero h1 {
    font-size: 4.5rem;
    margin-bottom: 1rem;
    color: white;
    text-shadow: 0 2px 4px rgba(0,0,0,0.2);
}

.hero .subtitle {
    font-size: 1.75rem;
    color: rgba(255, 255, 255, 0.9);
    margin-bottom: 2rem;
    font-weight: 500;
}

.hero p {
    max-width: 650px;
    margin: 0 auto 2.5rem;
    font-size: 1.1rem;
    color: rgba(255, 255, 255, 0.85);
}

.cta-button {
    background: var(--accent-gradient);
    color: white;
    border: none;
    padding: 1rem 2.5rem;
    border-radius: 50px;
    text-decoration: none;
    font-size: 1.1rem;
    font-weight: 700;
    transition: all 0.3s ease;
    box-shadow: 0 8px 20px rgba(79, 70, 229, 0.3);
}

.cta-button:hover {
    transform: translateY(-3px) scale(1.05);
    box-shadow: 0 12px 25px rgba(79, 70, 229, 0.4);
}

/* Navigation Bar */
.main-nav {
    background-color: var(--primary-bg);
    border-bottom: 1px solid var(--border-color);
    position: sticky;
    top: 0;
    z-index: 999;
    box-shadow: 0 2px 10px var(--shadow-color);
    transition: top 0.3s;
}

.main-nav ul {
    display: flex;
    justify-content: center;
    list-style: none;
    margin: 0;
    padding: 1rem 0;
}

.main-nav li {
    margin: 0 1.5rem;
}

.main-nav a {
    color: var(--light-text-color);
    text-decoration: none;
    font-weight: 700;
    font-size: 1rem;
    transition: color 0.3s;
    position: relative;
    padding-bottom: 0.5rem;
}

.main-nav a::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
    width: 0;
    height: 3px;
    background: var(--accent-gradient);
    transition: width 0.3s;
    border-radius: 2px;
}

.main-nav a:hover,
.main-nav a.active {
    color: var(--accent-color);
}

.main-nav a:hover::after,
.main-nav a.active::after {
    width: 100%;
}


/* General Section Styling */
section {
    padding: 6rem 0;
}

.features, .why-n-back {
    background-color: var(--secondary-bg);
}

.screenshots, .tech-stack {
    background-color: var(--primary-bg);
}

/* Features Section */
.feature-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
    gap: 2.5rem;
}

.feature-item {
    background: var(--card-bg);
    border: 1px solid var(--border-color);
    padding: 2.5rem;
    border-radius: 16px;
    text-align: center;
    transition: transform 0.3s, box-shadow 0.3s;
    box-shadow: 0 5px 15px var(--shadow-color);
}

.feature-item:hover {
    transform: translateY(-8px);
    box-shadow: 0 12px 25px rgba(0,0,0,0.1);
}

.feature-item h3 {
    font-size: 1.4rem;
    margin-bottom: 1rem;
    color: var(--text-color);
}

/* Why N-Back Section */
.why-n-back .container {
    display: flex;
    flex-direction: column;
    align-items: center;
}

.why-n-back-content {
    max-width: 800px;
    text-align: center;
}

.why-n-back-content p {
    font-size: 1.1rem;
    margin-bottom: 1.5rem;
}

/* Screenshots Section */
.screenshot-gallery {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
    gap: 2.5rem;
    max-width: 1000px;
    margin: 0 auto;
}

.screenshot-gallery figure {
    margin: 0;
    text-align: center;
    background: var(--card-bg);
    padding: 1rem;
    border-radius: 16px;
    border: 1px solid var(--border-color);
    box-shadow: 0 5px 15px var(--shadow-color);
    transition: transform 0.3s, box-shadow 0.3s;
}

.screenshot-gallery figure:hover {
    transform: translateY(-8px);
    box-shadow: 0 12px 25px rgba(0,0,0,0.1);
}

.screenshot-gallery img {
    width: 100%;
    height: auto;
    border-radius: 12px;
    cursor: pointer;
    margin-bottom: 1rem;
}

.screenshot-gallery figcaption {
    font-size: 1rem;
    color: var(--light-text-color);
    font-style: italic;
}

/* Tech Stack Section */
.tech-stack ul {
    list-style: none;
    padding: 0;
    display: flex;
    justify-content: center;
    flex-wrap: wrap;
    gap: 1.5rem;
}

.tech-stack li {
    background: var(--card-bg);
    color: var(--light-text-color);
    padding: 0.7rem 1.8rem;
    border-radius: 50px;
    font-size: 1rem;
    font-weight: 500;
    border: 1px solid var(--border-color);
    box-shadow: 0 2px 5px var(--shadow-color);
    transition: all 0.3s;
}

.tech-stack li:hover {
    transform: translateY(-3px);
    box-shadow: 0 5px 10px rgba(0,0,0,0.08);
}

/* Footer */
footer {
    background-color: var(--secondary-bg);
    text-align: center;
    padding: 3rem 0;
    color: var(--light-text-color);
    font-size: 1rem;
    border-top: 1px solid var(--border-color);
}

/* Modal for Screenshots */
.modal {
    display: none;
    position: fixed;
    z-index: 1000;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    overflow: auto;
    background-color: rgba(0, 0, 0, 0.9);
    justify-content: center;
    align-items: center;
    animation: fadeIn 0.3s;
}

@keyframes fadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
}

.modal-content {
    max-width: 90%;
    max-height: 90%;
    display: block;
    margin: auto;
    border-radius: 8px;
}

.close-modal {
    position: absolute;
    top: 25px;
    right: 40px;
    color: #f1f1f1;
    font-size: 50px;
    font-weight: bold;
    transition: 0.3s;
    cursor: pointer;
}

.close-modal:hover {
    color: #bbb;
}

/* Responsive */
@media (max-width: 768px) {
    .hero h1 {
        font-size: 3.5rem;
    }
    h2 {
        font-size: 2.2rem;
    }
    .screenshot-gallery {
        grid-template-columns: 1fr;
    }
}

/* How to Play Section */

.mechanics-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 2.5rem;
    max-width: 900px;
    margin: 0 auto;
}

.mechanics-grid .card {
    text-align: center;
    background: var(--card-bg);
    border: 1px solid var(--border-color);
    padding: 2.5rem;
    border-radius: 16px;
    box-shadow: 0 5px 15px var(--shadow-color);
}

.mechanics-grid .icon {
    font-size: 3.5rem;
    margin-bottom: 1rem;
    display: block;
}

.mechanics-grid h3 {
    font-size: 1.5rem;
    font-weight: 700;
    margin-bottom: 1rem;
}

.simulator-container {
    display: flex;
    gap: 2.5rem;
    background: var(--card-bg);
    border: 1px solid var(--border-color);
    padding: 2.5rem;
    border-radius: 16px;
    box-shadow: 0 5px 15px var(--shadow-color);
    margin-top: 2.5rem;
}

.visual-simulator {
    flex: 1;
    text-align: center;
}

.controls-simulator {
    flex: 1;
    padding-left: 2.5rem;
    border-left: 1px solid var(--border-color);
}

.grid-container {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 0.5rem;
    width: 240px;
    margin: 1rem auto;
}

.grid-cell {
    width: 75px;
    height: 75px;
    border: 2px solid var(--border-color);
    border-radius: 8px;
    transition: background-color 0.3s ease;
}

.current-stimulus {
    background-color: #90cdf4 !important;
    border-color: #2b6cb0 !important;
}

.n-back-match {
    background-color: #faf089 !important;
    border-color: #b7791f !important;
}

.audio-stimulus-display {
    text-align: center;
    margin-bottom: 2rem;
}

.audio-stimulus-display p:first-child {
    font-size: 1rem;
    color: var(--light-text-color);
}

#audio-stimulus {
    font-size: 5rem;
    font-weight: 800;
    color: var(--accent-color);
    height: 80px;
    line-height: 80px;
}

#audio-n-back {
    font-weight: 700;
}

.controls-group {
    text-align: center;
    margin-bottom: 2rem;
}

.controls-group p {
    font-weight: 500;
    margin-bottom: 0.5rem;
}

.n-level-buttons, .action-buttons {
    display: flex;
    justify-content: center;
    gap: 0.5rem;
}

.btn {
    border: none;
    border-radius: 8px;
    padding: 0.75rem 1.5rem;
    font-weight: 700;
    color: white;
    transition: background-color 0.3s, transform 0.2s;
    cursor: pointer;
    background-color: #a0aec0;
}

.btn:hover {
    background-color: #718096;
}

.btn.active {
    background-color: var(--accent-color);
    transform: scale(1.05);
    box-shadow: 0 5px 15px rgba(79, 70, 229, 0.3);
}

.btn-primary {
    background-color: var(--accent-color);
    width: 100%;
}
.btn-primary:hover {
    background-color: #4338ca;
}

#reset-btn {
    background: none;
    border: none;
    color: var(--light-text-color);
    margin-top: 1rem;
    cursor: pointer;
    font-weight: 500;
}
#reset-btn:hover {
    color: var(--text-color);
}

.explanation-box {
    margin-top: 2rem;
    padding: 1.5rem;
    border-radius: 12px;
    text-align: center;
    font-size: 1.1rem;
    line-height: 1.6;
    border: 1px solid;
}

.explanation-box.info {
    background-color: #ebf8ff;
    border-color: #90cdf4;
    color: #2b6cb0;
}

.explanation-box.success {
    background-color: #f0fff4;
    border-color: #9ae6b4;
    color: #2f855a;
}

.flow-timeline {
    position: relative;
    max-width: 700px;
    margin: 0 auto;
}

.timeline-line {
    position: absolute;
    left: 24px;
    top: 0;
    bottom: 0;
    width: 4px;
    background: var(--border-color);
    border-radius: 2px;
}

.timeline-item {
    position: relative;
    padding-left: 70px;
    margin-bottom: 2rem;
}

.timeline-dot {
    position: absolute;
    left: 0;
    top: 5px;
    width: 50px;
    height: 50px;
    border-radius: 50%;
    background: var(--accent-gradient);
    color: white;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.5rem;
    font-weight: 700;
    border: 4px solid var(--primary-bg);
}

@media (max-width: 768px) {
    .mechanics-grid, .simulator-container {
        grid-template-columns: 1fr;
        flex-direction: column;
    }
    .controls-simulator {
        padding-left: 0;
        border-left: none;
        border-top: 1px solid var(--border-color);
        padding-top: 2.5rem;
    }
}

