import i18n from 'i18next';
import { initReactI18next } from 'react-i18next';
import enTranslation from './locales/en.json';
import zhCnTranslation from './locales/zh_cn.json';
import { locale } from '@tauri-apps/plugin-os';

export type AppLanguage = 'en' | 'zh_cn';

/** Maps a system locale string to an app language. Shared with SettingsContext
 * so language detection lives in exactly one place. */
export const resolveSystemLanguage = (systemLocale: string | null): AppLanguage =>
  systemLocale?.toLowerCase().startsWith('zh') ? 'zh_cn' : 'en';

/** BCP 47 locale for date/number formatting, derived from the app language
 * (the app language tag `zh_cn` is not itself a valid BCP 47 tag). */
export const dateLocale = (language: string): string =>
  language === 'zh_cn' ? 'zh-CN' : 'en-US';

const CLIENT_SETTINGS_KEY = 'settings:client';

const resources = {
  en: {
    translation: enTranslation,
  },
  zh_cn: {
    translation: zhCnTranslation,
  },
};

/** Reads and parses a localStorage key; returns undefined on missing or
 * corrupted values instead of throwing (a corrupted value must not white-screen
 * the app at startup). */
const readJson = (key: string): unknown => {
  const raw = localStorage.getItem(key);
  if (raw === null) return undefined;
  try {
    return JSON.parse(raw);
  } catch (error) {
    console.error(`Ignoring corrupted localStorage key "${key}":`, error);
    return undefined;
  }
};

export const initializeI18n = async () => {
  const stored = (readJson(CLIENT_SETTINGS_KEY) ?? {}) as {
    language?: unknown;
    followSystemLanguage?: unknown;
  };
  const followSystem =
    typeof stored.followSystemLanguage === 'boolean' ? stored.followSystemLanguage : true;

  let language: AppLanguage;
  if (followSystem) {
    const systemLocale = await locale();
    language = resolveSystemLanguage(systemLocale);
    // Also update the stored language to reflect the system's one. Only merge
    // into an existing object so we never create a partially populated key.
    if (localStorage.getItem(CLIENT_SETTINGS_KEY) !== null) {
      localStorage.setItem(CLIENT_SETTINGS_KEY, JSON.stringify({ ...stored, language }));
    }
  } else {
    language = stored.language === 'zh_cn' ? 'zh_cn' : 'en';
  }

  return i18n
    .use(initReactI18next)
    .init({
      resources,
      lng: language,
      fallbackLng: 'en',
      interpolation: {
        escapeValue: false, // react already safes from xss
      },
    });
};

export default i18n;

import { HashRouter, Routes, Route } from "react-router-dom";
import { SettingsProvider } from "./contexts/SettingsContext";
import { GameStatusProvider } from "./contexts/GameStatusContext";
import { PauseProvider } from "./contexts/PauseContext";
import Layout from "./components/Layout"; // Import the new Layout component
import GamePage from "./pages/GamePage";
import SettingsPage from "./pages/SettingsPage";
import HistoryPage from "./pages/HistoryPage";
import HistoryDetailPage from "./pages/HistoryDetailPage";
import "./App.css";

function App() {
  return (
    <SettingsProvider>
      <GameStatusProvider>
        <PauseProvider>
          <HashRouter>
            <Routes>
              <Route path="/" element={<Layout />}>
            <Route index element={<GamePage />} />
            <Route path="settings" element={<SettingsPage />} />
            <Route path="history" element={<HistoryPage />} />
            <Route path="history/:sessionId" element={<HistoryDetailPage />} />
            <Route path="results/:sessionId" element={<HistoryDetailPage />} />
              </Route>
            </Routes>
          </HashRouter>
        </PauseProvider>
      </GameStatusProvider>
    </SettingsProvider>
  );
}

export default App;

